<script>
(()=>{const csrf=document.querySelector('meta[name="csrf-token"]')?.content||document.querySelector('#chatForm input[name="_token"]')?.value||'',messages=document.getElementById('chatMessages'),form=document.getElementById('chatForm'),input=document.getElementById('messageInput'),sendButton=document.getElementById('sendButton'),status=document.getElementById('chatStatus'),agentSelect=document.getElementById('agentSelect'),windowSelect=document.getElementById('windowSelect'),detailSummaryWrap=document.getElementById('detailSummaryWrap'),detailSummaryCards=document.getElementById('detailSummaryCards'),reportTitle=document.getElementById('reportTitle'),reportMeta=document.getElementById('reportMeta'),reportAssessment=document.getElementById('reportAssessment'),reportMessage=document.getElementById('reportMessage'),reportAction=document.getElementById('reportAction'),reportItems=document.getElementById('reportItems'),ministryUrl=@json(route('admin.najm-hoda.founder-ops.ministry.chat')),freeChatUrl=@json(route('admin.najm-hoda.chat.send'));let activePane='ministry',lastIntent='morning_brief';const labels={urgent:'فوری / مهم',founder_decisions:'منتظر تصمیم من',prepared:'آماده توسط نجم',information:'صرفاً جهت اطلاع',pending:'منتظر',overdue:'عقب‌افتاده',pending_decisions:'تصمیم ارتباطی',total:'مجموع',health_attention_items:'هشدار سلامت',runtime_status:'وضعیت runtime'};const domainLabels={users:'کاربران',invitations:'دعوت‌ها',support:'پشتیبانی',reports_moderation:'نظارت',moderation:'نظارت',reference_data:'داده پایه',locations:'مکان‌ها',approvals:'داده پایه',groups:'گروه‌ها',governance:'انتخابات',najm_bahar:'نجم بهار',financial_risk:'سلامت مالی',stock:'سهام',secretariat:'دبیرخانه',email:'ایمیل',blog:'محتوا',notifications:'اطلاعیه',runtime_health:'سلامت نجم',founder_approvals:'تصمیم مدیرکل',authority:'اختیارها'};function esc(v){const d=document.createElement('div');d.textContent=v==null?'':String(v);return d.innerHTML}function btnClass(s){return s==='success'?'btn-success':s==='outline-danger'?'btn-outline-danger':s==='primary'?'btn-primary':'btn-outline-primary'}function actionForm(a){const f=document.createElement('form');f.method='POST';f.action=a.url;f.className='nh-action-form';f.dataset.confirm=a.confirm?'1':'0';f.innerHTML=`<input type="hidden" name="_token" value="${esc(csrf)}">${a.decision?`<input type="hidden" name="decision" value="${esc(a.decision)}">`:''}<button type="submit" class="btn btn-sm ${btnClass(a.style)}">${esc(a.label||'اقدام')}</button>`;return f}function addConversation(text,who='bot'){const w=document.createElement('div');w.className=`nh-msg ${who}`;w.innerHTML=`<div class="nh-bubble"><strong>${who==='user'?'شما':'نجم هدا'}</strong><div class="mt-1">${esc(text)}</div></div>`;messages.appendChild(w);messages.scrollTop=messages.scrollHeight}function renderGlobal(c){if(!c)return;['urgent','founder_decisions','prepared','information'].forEach(k=>{const e=document.querySelector(`[data-global="${k}"]`);if(e&&Object.prototype.hasOwnProperty.call(c,k))e.textContent=c[k]})}function normalize(k,v){return v&&typeof v==='object'&&!Array.isArray(v)?{label:v.label||labels[k]||k,value:v.value??'—'}:{label:labels[k]||k,value:v}}function renderDetail(cards,intent){detailSummaryCards.innerHTML='';if(!cards||Object.keys(cards).length===0||['morning_brief','end_of_day'].includes(intent)){detailSummaryWrap.hidden=true;return}Object.entries(cards).slice(0,4).forEach(([k,v])=>{const x=normalize(k,v),c=document.createElement('div');c.className='nh-summary-card';c.innerHTML=`<div class="v">${esc(x.value)}</div><div class="k">${esc(x.label)}</div>`;detailSummaryCards.appendChild(c)});detailSummaryWrap.hidden=false}function renderItems(items){reportItems.innerHTML='';if(!items?.length){reportItems.innerHTML='<div class="nh-empty">موردی برای رسیدگی در این گزارش وجود ندارد.</div>';return}items.slice(0,20).forEach(item=>{const p=String(item.priority||item.risk||'P3').toLowerCase(),title=item.title||item.label||domainLabels[item.domain]||'مورد مدیریتی',kind=item.kind==='approval'?'منتظر تصمیم شما':item.kind==='proposal'?'آماده بررسی':(item.status||item.sla_status||'جهت اطلاع'),row=document.createElement('div');row.className='nh-item';row.innerHTML=`<div class="nh-item-top"><span>${esc(title)}</span><span class="nh-badge ${esc(p)}">${esc(item.priority||item.risk||'')}</span></div><div class="nh-item-meta">${esc(kind)}${item.domain?' · '+esc(domainLabels[item.domain]||item.domain):''}${item.entity_id?' · #'+esc(item.entity_id):''}</div>`;const a=document.createElement('div');a.className='nh-item-actions';if(item.ui?.workbench_url){const l=document.createElement('a');l.href=item.ui.workbench_url;l.className='btn btn-sm btn-outline-secondary';l.textContent='رسیدگی / جزئیات';a.appendChild(l)}(item.ui?.actions||[]).forEach(x=>a.appendChild(actionForm(x)));if(a.children.length)row.appendChild(a);reportItems.appendChild(row)})}function renderReport(d){const m=d.management||{},x=m.executive||{};lastIntent=m.intent||lastIntent;reportTitle.textContent=x.title||'گزارش مدیریتی';reportMeta.textContent=`بازه گزارش: ${x.window_hours||windowSelect.value||24} ساعت · ${m.items?.length||0} مورد کارت‌شده`;reportAssessment.textContent=x.assessment||'بررسی شد';const attention=!!(x.action_required||x.needs_founder_action);reportAssessment.classList.toggle('attention',attention);reportMessage.textContent=d.message||'گزارش آماده شد.';reportAction.textContent='اقدام شما: '+(x.action_text||'فعلاً اقدامی لازم نیست.');renderDetail(m.summary_cards||{},lastIntent);renderItems(m.items||[]);renderGlobal(m.global_summary_cards||(['morning_brief','end_of_day'].includes(lastIntent)?m.summary_cards:null))}async function requestJson(url,payload){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(payload)});let d={};try{d=await r.json()}catch(_){}if(!r.ok){const e=new Error(d.message||d.error||`HTTP ${r.status}`);e.payload=d;throw e}return d}async function runMinistry(payload,{conversation=false}={}){document.querySelectorAll('.nh-intent').forEach(b=>b.disabled=true);status.textContent='در حال خواندن وضعیت واقعی Founder Ops...';try{const d=await requestJson(ministryUrl,{...payload,hours:Number(windowSelect.value||24)});renderReport(d);if(conversation)addConversation(d.message||'گزارش به‌روزرسانی شد.','bot');status.textContent='گزارش جاری از داده‌های canonical Founder Ops به‌روزرسانی شد.';return d}catch(e){if(e.payload?.management?.meta?.reason==='unclassified_management_question'){if(conversation)addConversation(e.payload.message,'bot');status.textContent='این متن به intent خواندنی امن نگاشت نشد؛ هیچ اقدامی اجرا نشد.'}else{if(conversation)addConversation('امکان دریافت گزارش مدیریتی وجود نداشت: '+e.message,'bot');status.textContent='خطا در وزارت هوشمند.'}return null}finally{document.querySelectorAll('.nh-intent').forEach(b=>b.disabled=false)}}document.querySelectorAll('.nh-intent').forEach(b=>b.addEventListener('click',()=>runMinistry({intent:b.dataset.intent})));document.querySelectorAll('.nh-tab').forEach(t=>t.addEventListener('click',()=>{document.querySelectorAll('.nh-tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');activePane=t.dataset.pane;agentSelect.style.visibility=activePane==='ministry'?'hidden':'visible';windowSelect.style.visibility=activePane==='ministry'?'visible':'hidden';input.placeholder=activePane==='ministry'?'مثلاً: چرا این مورد را مهم تشخیص دادی؟':'سؤال خود را از نجم هدا بپرسید...'}));agentSelect.style.visibility='hidden';windowSelect.addEventListener('change',()=>runMinistry({intent:lastIntent}));form.addEventListener('submit',async e=>{e.preventDefault();const text=input.value.trim();if(!text)return;addConversation(text,'user');input.value='';sendButton.disabled=true;try{if(activePane==='ministry')await runMinistry({message:text},{conversation:true});else{const d=await requestJson(freeChatUrl,{message:text,agent:agentSelect.value});addConversation(d.response||d.message||'پاسخی دریافت نشد.','bot')}}catch(err){addConversation('خطا در گفت‌وگو: '+err.message,'bot')}finally{sendButton.disabled=false;input.focus()}});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}});document.addEventListener('submit',e=>{const f=e.target.closest('.nh-action-form');if(f&&f.dataset.confirm==='1'&&!window.confirm('این اقدام از lifecycle رسمی Founder Ops اجرا می‌شود. ادامه می‌دهید؟'))e.preventDefault()});runMinistry({intent:'morning_brief'});})();
</script>
@endpush